<?php
namespace WGMM;

final class Store {
    public static function table(string $name): string {global $wpdb;return $wpdb->prefix.'wgmm_'.$name;}
    public static function install(): void {
        global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$charset=$wpdb->get_charset_collate();
        dbDelta('CREATE TABLE '.self::table('workspaces')." (id bigint unsigned NOT NULL AUTO_INCREMENT, owner_id bigint unsigned NOT NULL, payer_id bigint unsigned NOT NULL, title varchar(200) NOT NULL, grant_type varchar(20) NOT NULL DEFAULT 'membership', document longtext NOT NULL, revision bigint unsigned NOT NULL DEFAULT 1, approved_version varchar(80) NOT NULL DEFAULT '', updated_at datetime NOT NULL, PRIMARY KEY  (id), KEY owner_id (owner_id)) ENGINE=InnoDB $charset;");
        dbDelta('CREATE TABLE '.self::table('members')." (workspace_id bigint unsigned NOT NULL, user_id bigint unsigned NOT NULL, role varchar(20) NOT NULL, PRIMARY KEY  (workspace_id,user_id), KEY user_id (user_id)) ENGINE=InnoDB $charset;");
        dbDelta('CREATE TABLE '.self::table('versions')." (id varchar(80) NOT NULL, workspace_id bigint unsigned NOT NULL, author_id bigint unsigned NOT NULL, snapshot longtext NOT NULL, foundation_hash varchar(64) NOT NULL, created_at datetime NOT NULL, PRIMARY KEY  (id), KEY workspace_id (workspace_id)) ENGINE=InnoDB $charset;");
        Sources::install();
        foreach(['workspaces','members','versions','sources'] as $name){$table=self::table($name);if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)))!==$table){throw new \RuntimeException('Message Matrix Pro tables could not be created. Check database permissions.',500);}}
        update_option('wgmm_schema','2',false);
    }
    public static function row(int $id): array {global $wpdb;$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('workspaces').' WHERE id=%d',$id),ARRAY_A);if(!$r){throw new \RuntimeException('Workspace not found.',404);}$d=json_decode($r['document'],true);if(!is_array($d)){throw new \RuntimeException('Workspace data could not be read. Contact the site administrator.',500);}$d['foundation_sources']=$d['foundation_sources']??[];$d['brand']=array_merge(Domain::blank()['brand'],$d['brand']);$r['document']=$d;$r['revision']=(int)$r['revision'];$r['id']=(int)$r['id'];$r['owner_id']=(int)$r['owner_id'];$r['payer_id']=(int)$r['payer_id'];return $r;}
    public static function role(int $id,int $user): string {global $wpdb;return (string)$wpdb->get_var($wpdb->prepare('SELECT role FROM '.self::table('members').' WHERE workspace_id=%d AND user_id=%d',$id,$user));}
    public static function membership_active(int $user): bool {
        $levels=get_option('wgmm_settings',[])['level_ids']??[];if(!$levels||!function_exists('wlmapi_get_member')){return false;}
        try{$r=wlmapi_get_member($user);if(empty($r['success'])){return false;}foreach(($r['member']??[]) as $member){foreach(($member['Levels']??[]) as $id=>$v){$v=(array)$v;if(in_array((string)($v['Level_ID']??$id),$levels,true)&&in_array($v['Active']??null,[1,'1',true],true)&&empty($v['Cancelled'])&&empty($v['Pending'])&&empty($v['UnConfirmed'])&&empty($v['Expired'])){return true;}}}}catch(\Throwable $e){}return false;
    }
    public static function writable(array $row): bool {return (bool)apply_filters('wgmm_workspace_entitled',$row['grant_type']==='complimentary'||self::membership_active($row['payer_id']),$row['id'],$row['payer_id']);}
    public static function access(int $id,string $action='read'): array {
        $row=self::row($id);$role=self::role($id,get_current_user_id());if(current_user_can('manage_options')){$role='owner';}
        if(!Domain::can($role,$action)){throw new \RuntimeException('Your company role does not allow this action.',403);}
        if($action!=='read'&&!($action==='team'&&current_user_can('manage_options'))&&!self::writable($row)){throw new \RuntimeException('This company is read-only. Renew Message Matrix Pro access or contact the site administrator.',403);}$row['role']=$role;$row['writable']=self::writable($row);return $row;
    }
    public static function listing(): array {
        global $wpdb;$w=self::table('workspaces');$m=self::table('members');$u=get_current_user_id();
        $rows=current_user_can('manage_options')?$wpdb->get_results("SELECT id,title FROM $w ORDER BY title,id LIMIT 200",ARRAY_A):$wpdb->get_results($wpdb->prepare("SELECT w.id,w.title FROM $w w INNER JOIN $m m ON w.id=m.workspace_id WHERE m.user_id=%d ORDER BY w.title,w.id LIMIT 200",$u),ARRAY_A);
        $out=[];foreach($rows as $r){$row=self::access((int)$r['id']);$out[]=['id'=>$row['id'],'title'=>$row['title'],'role'=>$row['role'],'writable'=>$row['writable']];}return $out;
    }
    public static function create(string $title,int $owner,bool $complimentary): int {
        global $wpdb;$admin=current_user_can('manage_options');if(!$admin&&($owner!==get_current_user_id()||$complimentary||!self::membership_active($owner))){throw new \RuntimeException('An active Message Matrix Pro membership is required.',403);}if(!get_userdata($owner)){throw new \InvalidArgumentException('Choose an existing site user as company owner.');}
        $key='wgmm_create_'.$owner;if(!add_option($key,time(),'','no')){if((int)get_option($key)<time()-120){delete_option($key);}throw new \RuntimeException('Another workspace is being created. Try again shortly.',409);}
        try{if(!$admin&&(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.self::table('workspaces').' WHERE payer_id=%d',$owner))>0){throw new \RuntimeException('Your membership already has a company workspace. Contact the administrator for another company.',409);}
            if($wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::table('workspaces').' WHERE owner_id=%d AND title=%s',$owner,$title))){throw new \RuntimeException('You already own a workspace with this name.',409);}
            $wpdb->query('START TRANSACTION');$ok=$wpdb->insert(self::table('workspaces'),['owner_id'=>$owner,'payer_id'=>$owner,'title'=>$title,'grant_type'=>$complimentary?'complimentary':'membership','document'=>wp_json_encode(Domain::blank()),'revision'=>1,'updated_at'=>gmdate('Y-m-d H:i:s')]);if(!$ok){throw new \RuntimeException('The workspace could not be created.',500);}$id=(int)$wpdb->insert_id;if(!$wpdb->insert(self::table('members'),['workspace_id'=>$id,'user_id'=>$owner,'role'=>'owner'])){throw new \RuntimeException('The owner could not be assigned.',500);}$wpdb->query('COMMIT');return $id;
        }catch(\Throwable $e){$wpdb->query('ROLLBACK');throw $e;}finally{delete_option($key);}
    }
    public static function members(int $id): array {
        global $wpdb;$rows=$wpdb->get_results($wpdb->prepare('SELECT user_id,role FROM '.self::table('members').' WHERE workspace_id=%d ORDER BY user_id',$id),ARRAY_A);$out=[];foreach($rows as $r){$u=get_userdata((int)$r['user_id']);$out[]=['user_id'=>(int)$r['user_id'],'name'=>$u?$u->display_name:'Unavailable site user','role'=>$r['role']];}return $out;
    }
    public static function payload(array $row): array {
        global $wpdb;return ['id'=>$row['id'],'title'=>$row['title'],'role'=>$row['role'],'writable'=>$row['writable'],'owner_id'=>$row['owner_id'],'revision'=>$row['revision'],'approved_version'=>$row['approved_version'],'updated_at'=>$row['updated_at'].' UTC','document'=>$row['document'],'source_documents'=>Sources::links($row),'available_sources'=>Sources::available(),'members'=>self::members($row['id']),'versions'=>$wpdb->get_results($wpdb->prepare('SELECT id,author_id,created_at,foundation_hash FROM '.self::table('versions').' WHERE workspace_id=%d ORDER BY created_at DESC LIMIT 100',$row['id']),ARRAY_A)];
    }
    /** Compare-and-swap prevents one tab or team member overwriting a newer save. */
    public static function cas(array $row,array $doc,string $approved): void {
        global $wpdb;$changed=$wpdb->query($wpdb->prepare('UPDATE '.self::table('workspaces').' SET document=%s,revision=revision+1,approved_version=%s,updated_at=%s WHERE id=%d AND revision=%d',wp_json_encode($doc),$approved,gmdate('Y-m-d H:i:s'),$row['id'],$row['revision']));if($changed===false){throw new \RuntimeException('The save failed. Your work has not been confirmed saved.',500);}if($changed!==1){throw new \RuntimeException('A newer version was saved in another tab or by your team. Download your unsaved copy, then reload before saving again.',409);}
    }
    public static function save(int $id,int $revision,array $raw): array {
        $row=self::access($id,'draft');if($row['revision']!==$revision){throw new \RuntimeException('A newer version exists. Download your unsaved copy and reload.',409);}$d=Domain::validate($raw);if($d['foundation_sources']!==$row['document']['foundation_sources']){throw new \InvalidArgumentException('Use the source upload or existing document action to change foundation documents.');}$keys=Domain::changed_keys($row['document'],$d);
        if(!Domain::can($row['role'],'plan')&&array_diff($keys,['assets'])){throw new \RuntimeException('Planning changes require Owner or Strategist access.',403);}
        Domain::guard_assets($row['document']['assets'],$d['assets'],$row['role'],get_current_user_id(),array_column(self::members($id),'user_id'));
        $foundation_changed=Domain::foundation_hash($row['document'])!==Domain::foundation_hash($d);$old=array_column($row['document']['campaigns'],null,'id');foreach($d['campaigns'] as &$c){if(isset($old[$c['id']])){if($c['foundation_version']!==$old[$c['id']]['foundation_version']){throw new \InvalidArgumentException('Use the explicit campaign foundation action to change its approved source.');}}else{$c['foundation_version']=$foundation_changed?'':$row['approved_version'];}}unset($c);
        $foundation_changed=Domain::foundation_hash($row['document'])!==Domain::foundation_hash($d);self::cas($row,$d,$foundation_changed?'':$row['approved_version']);return self::payload(self::access($id));
    }
    public static function approve_foundation(int $id,int $revision): array {
        global $wpdb;$row=self::access($id,'plan');if($row['revision']!==$revision){throw new \RuntimeException('Reload the latest foundation before approving.',409);}$d=$row['document'];foreach($d['foundation_sources'] as $source){$key=$source['kind'].'_implications';if(!trim($d['brand'][$key]??'')){throw new \InvalidArgumentException('Record the implications of each attached source in Step 1 before approving the foundation.');}}foreach(['story','promises','beliefs','trust','positioning','voice'] as $k){if(trim($d['brand'][$k])===''){throw new \InvalidArgumentException('Complete the Brand Story, Promises, Beliefs, Trust, positioning and voice before approval.');}}
        if(!$d['audiences']||!$d['buckets']||!$d['cells']||!$d['channel_plans']){throw new \InvalidArgumentException('Add audiences, buckets, at least one message path and its channel approach before approving the foundation.');}
        foreach($d['channel_plans'] as $channel){if(!trim($channel['approach'])){throw new \InvalidArgumentException('Complete each channel approach before approving the foundation.');}}
        foreach($d['cells'] as $c){if(!$c['message']&&!$c['unused_reason']){throw new \InvalidArgumentException('Give each selected Matrix cell a message or a reason it is unused.');}if($c['message']&&!array_filter($d['channel_plans'],static fn($p)=>$p['cell_id']===$c['id'])){throw new \InvalidArgumentException('Add a channel approach for every active message path.');}}
        $version='foundation_'.wp_generate_uuid4();$wpdb->query('START TRANSACTION');try{$ok=$wpdb->insert(self::table('versions'),['id'=>$version,'workspace_id'=>$id,'author_id'=>get_current_user_id(),'snapshot'=>wp_json_encode(Domain::foundation($d)),'foundation_hash'=>Domain::foundation_hash($d),'created_at'=>gmdate('Y-m-d H:i:s')]);if(!$ok){throw new \RuntimeException('The foundation snapshot could not be saved.',500);}self::cas($row,$d,$version);$wpdb->query('COMMIT');}catch(\Throwable $e){$wpdb->query('ROLLBACK');throw $e;}return self::payload(self::access($id));
    }
    public static function asset_status(int $id,int $revision,string $asset_id,string $operation,string $feedback=''): array {
        $row=self::access($id,'approve');if($row['revision']!==$revision){throw new \RuntimeException('Reload the latest asset before approval.',409);}$d=$row['document'];$found=false;$campaigns=array_column($d['campaigns'],null,'id');
        foreach($d['assets'] as &$a){if($a['id']!==$asset_id){continue;}$found=true;$a=Domain::review_transition($d,$a,$row['approved_version'],$operation,$feedback);}unset($a);if(!$found){throw new \RuntimeException('Asset not found.',404);}self::cas($row,$d,$row['approved_version']);return self::payload(self::access($id));
    }
    public static function pin_campaign(int $id,int $revision,string $campaign_id): array {
        $row=self::access($id,'plan');if($row['revision']!==$revision){throw new \RuntimeException('Reload the latest campaign before changing its foundation.',409);}if(!$row['approved_version']){throw new \InvalidArgumentException('Approve the current foundation first.');}$d=$row['document'];foreach($d['assets'] as $a){if($a['campaign_id']===$campaign_id&&$a['status']==='approved'){throw new \InvalidArgumentException('Reopen approved campaign assets before changing their foundation source.');}}$found=false;foreach($d['campaigns'] as &$c){if($c['id']===$campaign_id){$c['foundation_version']=$row['approved_version'];$found=true;}}unset($c);if(!$found){throw new \RuntimeException('Campaign not found.',404);}self::cas($row,$d,$row['approved_version']);return self::payload(self::access($id));
    }
    public static function team(int $id,int $revision,string $email,string $role,bool $remove): array {
        global $wpdb;$row=self::access($id,'team');if($row['revision']!==$revision){throw new \RuntimeException('Reload the latest team before changing access.',409);}$u=get_user_by('email',$email);if(!$u){throw new \InvalidArgumentException('This first build supports existing site users only. Create their site login first; no course membership is required.');}$uid=(int)$u->ID;if($uid===$row['owner_id']){throw new \InvalidArgumentException('The company owner cannot be removed or changed through team editing.');}Domain::choice($role,['strategist','contributor','reviewer','viewer']);$members=self::members($id);$exists=in_array($uid,array_column($members,'user_id'),true);$limit=max(1,min(50,(int)(get_option('wgmm_settings',[])['seat_limit']??5)));if(!$remove&&!$exists&&count($members)>=$limit){throw new \InvalidArgumentException('The company seat allowance has been reached.');}
        if($remove){foreach($row['document']['assets'] as $asset){if($asset['assigned_user_id']===$uid){throw new \InvalidArgumentException('Reassign this member’s assets before removing their access.');}}}
        $wpdb->query('START TRANSACTION');try{self::cas($row,$row['document'],$row['approved_version']);$ok=$remove?$wpdb->delete(self::table('members'),['workspace_id'=>$id,'user_id'=>$uid]):$wpdb->replace(self::table('members'),['workspace_id'=>$id,'user_id'=>$uid,'role'=>$role]);if($ok===false){throw new \RuntimeException('The team change failed.',500);}$wpdb->query('COMMIT');}catch(\Throwable $e){$wpdb->query('ROLLBACK');throw $e;}return self::payload(self::access($id));
    }
    public static function version(int $id,string $version): array {global $wpdb;self::access($id);$r=$wpdb->get_row($wpdb->prepare('SELECT id,snapshot,created_at FROM '.self::table('versions').' WHERE workspace_id=%d AND id=%s',$id,$version),ARRAY_A);if(!$r){throw new \RuntimeException('Foundation version not found.',404);}$r['snapshot']=json_decode($r['snapshot'],true);return $r;}
}
